/* ─────────────────────────────────────────────
   New landing-page style loading screen
   ───────────────────────────────────────────── */
.ls-page {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  flex-direction: column;
  align-items: center;
  overflow: hidden;
  font-family: "Inter", -apple-system, sans-serif;
  color: #fff;
  background: #060b18;
}

/* ── Background ── */
.ls-bg {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 80% 60% at 50% 0%, rgba(30, 58, 138, 0.55) 0%, transparent 70%), radial-gradient(ellipse 60% 40% at 20% 80%, rgba(17, 24, 39, 0.8) 0%, transparent 70%), #060b18;
  z-index: 0;
}

/* Big blurred watermark text */
.ls-bg-text {
  position: absolute;
  top: 45%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: clamp(6rem, 20vw, 18rem);
  font-weight: 900;
  letter-spacing: -0.02em;
  color: rgba(30, 58, 138, 0.18);
  filter: blur(2px);
  pointer-events: none;
  user-select: none;
  white-space: nowrap;
  z-index: 1;
}

/* ── Ticker ── */
.ls-ticker {
  width: 100%;
  background: rgba(15, 23, 42, 0.95);
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  overflow: hidden;
  height: 36px;
  display: flex;
  align-items: center;
  position: relative;
  z-index: 10;
  flex-shrink: 0;
}
.ls-ticker::before, .ls-ticker::after {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  width: 60px;
  z-index: 2;
}
.ls-ticker::before {
  left: 0;
  background: linear-gradient(90deg, rgba(15, 23, 42, 0.95), transparent);
}
.ls-ticker::after {
  right: 0;
  background: linear-gradient(-90deg, rgba(15, 23, 42, 0.95), transparent);
}
.ls-ticker__track {
  display: flex;
  align-items: center;
  gap: 0;
  white-space: nowrap;
  animation: ticker-scroll 35s linear infinite;
  will-change: transform;
}
.ls-ticker__item {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0 1.6rem;
  font-size: 0.82rem;
  font-weight: 600;
  border-right: 1px solid rgba(255, 255, 255, 0.07);
}
.ls-ticker__arrow.up {
  color: #22c55e;
}
.ls-ticker__arrow.down {
  color: #ef4444;
}
.ls-ticker__name {
  color: rgba(255, 255, 255, 0.75);
}
.ls-ticker__chg {
  font-weight: 700;
}
.ls-ticker__chg.up {
  color: #22c55e;
}
.ls-ticker__chg.down {
  color: #ef4444;
}

@keyframes ticker-scroll {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-33.333%);
  }
}
/* ── Loading screen logo ── */
.ls-logo {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 1.6rem;
}
.ls-logo__ring {
  position: relative;
  width: 56px;
  height: 56px;
  flex-shrink: 0;
}
.ls-logo__svg {
  width: 56px;
  height: 56px;
  filter: drop-shadow(0 0 10px rgba(34, 197, 94, 0.5));
  animation: ls-logo-spin 12s linear infinite;
}
.ls-logo__glow {
  position: absolute;
  inset: 6px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(34, 197, 94, 0.18), transparent 70%);
  pointer-events: none;
}
.ls-logo__wordmark {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
}
.ls-logo__name {
  font-family: "Orbitron", sans-serif;
  font-size: 1.4rem;
  font-weight: 900;
  color: #fff;
  letter-spacing: 0.04em;
  line-height: 1;
}
.ls-logo__name-hl {
  color: #22c55e;
}
.ls-logo__tagline {
  font-size: 0.58rem;
  letter-spacing: 0.14em;
  color: rgba(255, 255, 255, 0.35);
  font-weight: 600;
  text-transform: uppercase;
}

@keyframes ls-logo-spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}
/* WhatsApp CTA button in hero */
.ls-hero__wa-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: #25D366;
  color: #000;
  font-size: 0.78rem;
  font-weight: 700;
  padding: 0.5rem 1.1rem;
  border-radius: 2rem;
  text-decoration: none;
  transition: opacity 0.15s, transform 0.15s;
}
.ls-hero__wa-link:hover {
  opacity: 0.9;
  transform: translateY(-1px);
}

/* ── Hero ── */
.ls-hero {
  position: relative;
  z-index: 5;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 2.8rem 2rem 0;
  max-width: 860px;
  width: 100%;
  flex-shrink: 0;
}
.ls-hero__badge {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: rgba(147, 197, 253, 0.8);
  background: rgba(59, 130, 246, 0.12);
  border: 1px solid rgba(59, 130, 246, 0.25);
  border-radius: 2rem;
  padding: 0.28rem 1rem;
  margin-bottom: 1.2rem;
  text-transform: uppercase;
}
.ls-hero__title {
  font-size: clamp(2.4rem, 6vw, 4rem);
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -0.02em;
  margin: 0 0 1rem;
  color: #fff;
}
.ls-hero__title-hl {
  background: linear-gradient(135deg, #3b82f6, #8b5cf6, #06b6d4);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.ls-hero__sub {
  font-size: 1rem;
  color: rgba(203, 213, 225, 0.75);
  line-height: 1.6;
  max-width: 560px;
  margin: 0 auto 1.8rem;
  font-weight: 400;
}
.ls-hero__cta {
  display: flex;
  align-items: center;
  gap: 0.8rem;
  flex-wrap: wrap;
  justify-content: center;
  margin-bottom: 0.5rem;
}
.ls-hero__explore {
  font-size: 0.88rem;
  color: rgba(147, 197, 253, 0.7);
  text-decoration: none;
  font-weight: 500;
  transition: color 0.15s;
}
.ls-hero__explore:hover {
  color: #93c5fd;
}

/* CTA buttons */
.ls-btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.7rem 1.6rem;
  border-radius: 0.55rem;
  background: linear-gradient(135deg, #2563eb, #3b82f6);
  color: #fff;
  font-size: 0.95rem;
  font-weight: 700;
  border: none;
  cursor: pointer;
  font-family: inherit;
  box-shadow: 0 4px 20px rgba(59, 130, 246, 0.35);
  transition: all 0.15s;
}
.ls-btn-primary:hover {
  transform: translateY(-1px);
  box-shadow: 0 6px 24px rgba(59, 130, 246, 0.5);
}

.ls-btn-secondary {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.7rem 1.6rem;
  border-radius: 0.55rem;
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
  font-size: 0.95rem;
  font-weight: 700;
  border: 1px solid rgba(255, 255, 255, 0.18);
  cursor: pointer;
  font-family: inherit;
  transition: all 0.15s;
}
.ls-btn-secondary:hover {
  background: rgba(255, 255, 255, 0.12);
}

/* ── Testimonials ── */
.ls-testimonials {
  position: relative;
  z-index: 5;
  display: flex;
  gap: 1rem;
  padding: 1.4rem 1.5rem 0;
  width: 100%;
  max-width: 1100px;
  overflow-x: auto;
  flex-shrink: 0;
  scrollbar-width: none;
}
.ls-testimonials::-webkit-scrollbar {
  display: none;
}

.ls-tc {
  flex: 1;
  min-width: 230px;
  max-width: 340px;
  background: rgba(15, 23, 42, 0.8);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 1rem;
  padding: 1.1rem 1.2rem;
  backdrop-filter: blur(12px);
}
.ls-tc__stars {
  color: #f59e0b;
  font-size: 0.85rem;
  margin-bottom: 0.65rem;
  letter-spacing: 0.05em;
}
.ls-tc__avatar {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.9rem;
  font-weight: 800;
  color: #fff;
  margin-bottom: 0.5rem;
}
.ls-tc__name {
  font-size: 0.92rem;
  font-weight: 700;
  color: #e2e8f0;
  margin-bottom: 0.12rem;
}
.ls-tc__role {
  font-size: 0.76rem;
  color: rgba(148, 163, 184, 0.7);
  margin-bottom: 0.55rem;
}
.ls-tc__text {
  font-size: 0.83rem;
  color: rgba(203, 213, 225, 0.8);
  line-height: 1.55;
  margin: 0;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* ── Feature cards ── */
.ls-features {
  position: relative;
  z-index: 5;
  display: flex;
  gap: 0;
  width: 100%;
  max-width: 1100px;
  padding: 1.2rem 1.5rem 0;
  flex-shrink: 0;
}

.ls-feat {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 0.8rem 1rem;
  background: rgba(15, 23, 42, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.07);
  gap: 0.2rem;
}
.ls-feat:first-child {
  border-radius: 0.6rem 0 0 0.6rem;
}
.ls-feat:last-child {
  border-radius: 0 0.6rem 0.6rem 0;
}
.ls-feat:not(:first-child) {
  border-left: none;
}
.ls-feat__icon {
  font-size: 1.1rem;
}
.ls-feat__icon.live {
  color: #22c55e;
  animation: live-pulse 1.5s infinite;
}
.ls-feat__title {
  font-size: 1rem;
  font-weight: 800;
  color: #f1f5f9;
}
.ls-feat__title.small {
  font-size: 0.72rem;
}
.ls-feat__sub {
  font-size: 0.7rem;
  color: rgba(100, 116, 139, 0.9);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

@keyframes live-pulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
}
/* ── Loading bar (bottom) ── */
.ls-loading-bar {
  position: relative;
  z-index: 10;
  width: 100%;
  display: flex;
  align-items: center;
  gap: 0.8rem;
  padding: 0.6rem 1.5rem;
  margin-top: auto;
  background: rgba(6, 11, 24, 0.95);
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  flex-shrink: 0;
}
.ls-loading-bar__phrase {
  font-size: 0.76rem;
  color: rgba(148, 163, 184, 0.65);
  font-weight: 500;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  flex: 1;
}
.ls-loading-bar__track {
  width: 200px;
  flex-shrink: 0;
  height: 5px;
  background: rgba(255, 255, 255, 0.08);
  border-radius: 5px;
  overflow: hidden;
}
.ls-loading-bar__fill {
  height: 100%;
  background: linear-gradient(90deg, #1d4ed8, #3b82f6, #06b6d4);
  border-radius: 5px;
}
.ls-loading-bar__pct {
  font-size: 0.78rem;
  font-weight: 700;
  color: rgba(147, 197, 253, 0.8);
  min-width: 32px;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

/* ── Responsive ── */
@media (max-width: 760px) {
  .ls-hero {
    padding: 1.8rem 1.2rem 0;
  }
  .ls-hero__title {
    font-size: 2rem;
  }
  .ls-testimonials {
    padding: 1rem;
  }
  .ls-features {
    flex-direction: column;
    padding: 1rem;
    gap: 0.5rem;
  }
  .ls-feat {
    border-radius: 0.5rem !important;
    border-left: 1px solid rgba(255, 255, 255, 0.07) !important;
  }
  .ls-loading-bar__track {
    width: 120px;
  }
}
/* ═══════════════════════════════════════════════
   PHASE 2 — Centered AHMED TRADE loading screen
   ═══════════════════════════════════════════════ */
.ls2-page {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: grid;
  grid-template-columns: 200px 1fr 200px;
  grid-template-rows: 1fr auto;
  align-items: center;
  background: radial-gradient(ellipse 70% 60% at 50% 30%, rgba(6, 40, 100, 0.7) 0%, transparent 70%), radial-gradient(ellipse 40% 40% at 20% 80%, rgba(0, 180, 220, 0.08) 0%, transparent 60%), #060b18;
  font-family: "Orbitron", "Inter", monospace;
  color: #fff;
  overflow: hidden;
  /* subtle grid lines */
}
.ls2-page::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: linear-gradient(rgba(0, 180, 255, 0.04) 1px, transparent 1px), linear-gradient(90deg, rgba(0, 180, 255, 0.04) 1px, transparent 1px);
  background-size: 60px 60px;
  pointer-events: none;
}

/* Top-right tagline */
.ls2-tagline {
  position: absolute;
  top: 1.4rem;
  right: 1.8rem;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: rgba(0, 220, 255, 0.55);
  text-align: right;
  text-transform: uppercase;
  line-height: 1.5;
}

/* Left & Right sidebar feature cards */
.ls2-left-cards,
.ls2-right-cards {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  padding: 1.2rem 0.8rem;
  z-index: 2;
}

.ls2-feat-card {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(0, 200, 255, 0.12);
  border-radius: 0.7rem;
  padding: 0.65rem 0.9rem;
  backdrop-filter: blur(6px);
  transition: border-color 0.2s;
}
.ls2-feat-card.right {
  flex-direction: row-reverse;
  text-align: right;
}
.ls2-feat-card:hover {
  border-color: rgba(0, 200, 255, 0.28);
}

.ls2-feat-icon {
  font-size: 1.4rem;
  flex-shrink: 0;
}

.ls2-feat-title {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: #e2e8f0;
  text-transform: uppercase;
}

.ls2-feat-sub {
  font-size: 0.65rem;
  color: rgba(148, 163, 184, 0.7);
  font-family: "Inter", sans-serif;
  margin-top: 0.15rem;
  font-weight: 400;
  letter-spacing: 0.02em;
}

/* ── Center ── */
.ls2-center {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  z-index: 2;
  text-align: center;
  padding: 1.5rem 1rem;
}

/* AT logo ring */
.ls2-logo-ring {
  position: relative;
  width: 100px;
  height: 100px;
  border-radius: 50%;
  border: 2px solid rgba(0, 200, 255, 0.35);
  box-shadow: 0 0 30px rgba(0, 200, 255, 0.18), 0 0 80px rgba(0, 120, 255, 0.12), inset 0 0 30px rgba(0, 80, 200, 0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle, rgba(0, 50, 120, 0.6) 0%, rgba(6, 11, 24, 0.9) 70%);
  animation: ls2-ring-pulse 3s ease-in-out infinite;
}
.ls2-logo-ring::before {
  content: "";
  position: absolute;
  inset: -8px;
  border-radius: 50%;
  border: 1px solid rgba(0, 200, 255, 0.1);
  animation: ls2-ring-spin 12s linear infinite;
}
.ls2-logo-ring::after {
  content: "";
  position: absolute;
  inset: 4px;
  border-radius: 50%;
  border: 1px dashed rgba(0, 200, 255, 0.15);
}

.ls2-logo-inner {
  font-size: 2rem;
  font-weight: 900;
  color: #fff;
  letter-spacing: -0.02em;
  text-shadow: 0 0 20px rgba(0, 200, 255, 0.6);
  font-family: "Orbitron", monospace;
}

.ls2-logo-tick {
  position: absolute;
  top: -6px;
  right: -6px;
  width: 22px;
  height: 22px;
  background: #00c8ff;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 900;
  color: #060b18;
  box-shadow: 0 0 12px rgba(0, 200, 255, 0.6);
  animation: ls2-ring-spin 4s linear infinite reverse;
}

@keyframes ls2-ring-pulse {
  0%, 100% {
    box-shadow: 0 0 30px rgba(0, 200, 255, 0.18), 0 0 80px rgba(0, 120, 255, 0.12), inset 0 0 30px rgba(0, 80, 200, 0.15);
  }
  50% {
    box-shadow: 0 0 50px rgba(0, 200, 255, 0.32), 0 0 120px rgba(0, 120, 255, 0.2), inset 0 0 40px rgba(0, 100, 220, 0.25);
  }
}
@keyframes ls2-ring-spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}
/* Brand title */
.ls2-brand {
  font-size: clamp(2rem, 5vw, 3.2rem);
  font-weight: 900;
  letter-spacing: 0.15em;
  color: #fff;
  text-shadow: 0 0 40px rgba(0, 200, 255, 0.35);
  margin: 0;
}
.ls2-brand span {
  color: #00c8ff;
}

.ls2-brand-sub {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  color: rgba(148, 163, 184, 0.7);
  margin: 0;
  font-family: "Inter", sans-serif;
  text-transform: uppercase;
}

/* Loading text */
.ls2-loading-text {
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.25em;
  color: rgba(0, 200, 255, 0.8);
  text-transform: uppercase;
}
.ls2-loading-text span {
  animation: ls2-blink 0.9s step-end infinite;
  color: #00c8ff;
}

@keyframes ls2-blink {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0;
  }
}
/* Progress bar */
.ls2-bar-wrap {
  display: flex;
  align-items: center;
  gap: 0.8rem;
  width: 340px;
  max-width: 90%;
}

.ls2-bar-track {
  flex: 1;
  height: 6px;
  background: rgba(255, 255, 255, 0.08);
  border-radius: 10px;
  overflow: hidden;
  box-shadow: inset 0 0 0 1px rgba(0, 200, 255, 0.12);
}

.ls2-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, #1d4ed8, #0ea5e9, #00c8ff);
  border-radius: 10px;
  box-shadow: 0 0 10px rgba(0, 200, 255, 0.5);
}

.ls2-bar-pct {
  font-size: 0.85rem;
  font-weight: 700;
  color: #00c8ff;
  min-width: 36px;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.ls2-phrase {
  font-size: 0.72rem;
  color: rgba(148, 163, 184, 0.6);
  font-family: "Inter", sans-serif;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  font-weight: 500;
}

/* ── Bottom bar ── */
.ls2-bottom {
  grid-column: 1/-1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3rem;
  padding: 0.9rem 2rem;
  background: rgba(0, 0, 0, 0.35);
  border-top: 1px solid rgba(0, 200, 255, 0.08);
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  color: rgba(100, 116, 139, 0.7);
  text-transform: uppercase;
  z-index: 2;
  flex-wrap: wrap;
}

/* responsive phase 2 */
@media (max-width: 700px) {
  .ls2-page {
    grid-template-columns: 1fr;
    grid-template-rows: auto;
    padding: 2rem 1rem;
  }
  .ls2-left-cards, .ls2-right-cards {
    display: none;
  }
  .ls2-tagline {
    display: none;
  }
  .ls2-center {
    width: 100%;
  }
  .ls2-bottom {
    gap: 1rem;
  }
}






