html {
  font-family: system-ui, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif,
    'Apple Color Emoji', 'Segoe UI Emoji';
  line-height: 1.15;
  -webkit-text-size-adjust: 100%;
  -moz-tab-size: 4;
  tab-size: 4;
}
/* Sections ======== */
body {
  margin: 0;
}
/* Grouping content ================ */
hr {
  height: 0;
  color: inherit;
}
/* Text-level semantics ==================== */
abbr[title] {
  text-decoration: underline dotted;
}
code,
kbd,
samp,
pre {
  font-family: ui-monospace, SFMono-Regular, Consolas, 'Liberation Mono', Menlo,
    monospace;
  font-size: 1em;
}
small {
  font-size: 80%;
}
sub,
sup {
  font-size: 75%;
  line-height: 0;
  position: relative;
  vertical-align: baseline;
}
sub {
  bottom: -0.25em;
}
sup {
  top: -0.5em;
}
/* Tabular data ============ */
table {
  text-indent: 0;
  border-color: inherit;
}
/* Forms ===== */
button,
input,
optgroup,
select,
textarea {
  font-family: inherit;
  font-size: 100%;
  line-height: 1.15;
  margin: 0;
}
button,
select {
  text-transform: none;
}
button,
[type='button'],
[type='reset'],
[type='submit'] {
  -webkit-appearance: button;
}
::-moz-focus-inner {
  border-style: none;
  padding: 0;
}
:-moz-focusring {
  outline: 1px dotted ButtonText;
}
:-moz-ui-invalid {
  box-shadow: none;
}
legend {
  padding: 0;
}
progress {
  vertical-align: baseline;
}
::-webkit-inner-spin-button,
::-webkit-outer-spin-button {
  height: auto;
}
[type='search'] {
  -webkit-appearance: textfield;
  outline-offset: -2px;
}
::-webkit-search-decoration {
  -webkit-appearance: none;
}
::-webkit-file-upload-button {
  -webkit-appearance: button;
  font: inherit;
}
/* Interactive =========== */
summary {
  display: list-item;
}
body {
  margin: 0;
  line-height: normal;
}
.quill-ui-next-component,
.quill-ui-next-atom {
  display: flex;
  outline: none;
  position: relative;
}
.quill-ui-next-full-width {
  width: 100%;
}
.quill-ui-next-hide {
  display: none !important;
}
.quill-ui-next-fit-content {
  width: fit-content !important;
}
.quill-ui-next-column {
  flex-direction: column;
}
/* Placeholder default colors */
.quill-ui-next-component input::placeholder,
.quill-ui-next-atom input::placeholder {
  color: var(--component-field-placeholder-color);
}
.quill-ui-next-component input:disabled::placeholder,
.quill-ui-next-atom input:disabled::placeholder {
  color: var(--component-field-input-color-disabled);
}
/* Input Textfield Normal Icon colors */
.quill-ui-next-atom-textfield[data-state="disabled"] .textfield-icon svg {
  fill: var(--component-field-input-color-disabled) !important;
}
.quill-ui-next-hidden {
  display: none !important;
}
.quill-ui-next-pointer {
