/** @define barspinner */
.barspinner {
  margin: auto;
  width: 6rem;
  height: 2rem;
  white-space: nowrap;
}
.barspinner__rect {
  margin: 0.4rem;
  border-radius: 20px;
  height: 60%;
  width: 0.6rem;
  display: inline-block;
  animation: sk-stretchdelay 1.2s infinite ease-in-out;
}
.barspinner__rect--1 {
  animation-delay: -1.2s;
}
.barspinner__rect--2 {
  animation-delay: -1.1s;
}
.barspinner__rect--3 {
  animation-delay: -1s;
}
.barspinner__rect--4 {
  animation-delay: -0.9s;
}
.barspinner__rect--5 {
  animation-delay: -0.8s;
}
.barspinner--dark .barspinner__rect {
  background-color: var(--brand-secondary);
}

@keyframes sk-stretchdelay {
  0%, 40%, 100% {
    transform: scaleY(1);
  }
  20% {
    transform: scaleY(2);
  }
}
/** @define initial-loader */
