  font-size: 1.4rem;
  color: var(--text-general);
  font-weight: 700;
  text-transform: unset;
  text-align: center;
  line-height: 1.5;
  color: var(--text-general);
  padding-right: 0.8rem;
  pointer-events: none;
}
.dc-btn__icon--circle {
  padding-right: 0;
}
.dc-btn:not([disabled]):hover {
  text-decoration: none;
}
.dc-btn__rounded {
  border-radius: 24px;
}
.dc-btn--plus {
  width: 2.4rem;
  height: 2.4rem !important;
  border: 1px solid var(--border-hover) !important;
  padding: 0 !important;
  background: inherit;
  background-repeat: no-repeat;
  background-position: center;
}
.dc-btn--circle {
  height: 3.2rem;
  width: 3.2rem !important;
  border-radius: 50%;
}
.dc-btn--circular {
  border-radius: 100px;
}
.dc-btn--transparent {
