.dc-dialog {
  width: 100vw;
  height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  flex-direction: column;
  z-index: 999;
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
}
.dc-dialog__wrapper {
  position: fixed;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 999;
  transition: opacity 0.25s cubic-bezier(0.25, 0.1, 0.1, 0.25);
  background-color: var(--overlay-outside-dialog);
}
.dc-dialog__wrapper--enter, .dc-dialog__wrapper--exit {
  opacity: 0;
}
.dc-dialog__wrapper--enter .dc-dialog__dialog, .dc-dialog__wrapper--exit .dc-dialog__dialog {
  transform: translate3d(0, 50px, 0);
  opacity: 0;
}
.dc-dialog__wrapper--enter-done {
  opacity: 1;
}
.dc-dialog__wrapper--enter-done .dc-dialog__dialog {
  transform: translate3d(0, 0, 0);
  opacity: 1;
}
.dc-dialog__wrapper--has-portal {
  background-color: transparent;
}
.dc-dialog__dialog {
  max-width: 560px;
  max-height: 400px;
  min-width: 440px;
  min-height: 176px;
  margin-top: -48px;
