/* ═══════════════════════════════════════════════════════════════
   MARKSYNTRADER — GLOBAL RESPONSIVE SYSTEM
   Targets:
     • Mobile  xs  : ≤ 480px   (Galaxy S25 6.2", S25+ 6.5")
     • Mobile  sm  : 481–600px  (large phones, landscape)
     • Tablet      : 601–900px
     • Desktop sm  : 901–1280px (13.3" scaled)
     • Desktop md  : 1281–1919px (15.6" Vivobook, 13.3" native)
     • Desktop lg  : ≥ 1920px  (24" monitors)
   ═══════════════════════════════════════════════════════════════ */
/* ─── Touch targets: all interactive elements ≥ 44px on mobile ── */
@media (max-width: 600px) {
  button,
  .dc-tabs__item,
  [role=tab],
  [role=button],
  a {
    min-height: 44px;
    -webkit-tap-highlight-color: transparent;
  }
}
/* ═══ 1. ROOT FONT SCALING ═══════════════════════════════════════
   Base: 62.5% = 1rem → 10px (desktop)
   Scale down on small screens so rem-based sizing shrinks naturally. */
html {
  font-size: 62.5%; /* 1rem = 10px — desktop base */
}
@media (max-width: 1280px) and (min-width: 901px) {
  html {
    font-size: 58%; /* 13.3" laptop */
  }
}
@media (max-width: 900px) and (min-width: 601px) {
  html {
    font-size: 55%; /* tablets */
  }
}
@media (max-width: 600px) and (min-width: 481px) {
  html {
    font-size: 52%; /* large phones */
  }
}
@media (max-width: 480px) {
  html {
    font-size: 50%; /* phones — 1rem = 5px; buttons stay legible */
  }
}
@media (min-width: 1920px) {
  html {
    font-size: 65%; /* 24" monitor — slight upscale */
  }
}

/* ═══ 2. LAYOUT SHELL ════════════════════════════════════════════ */
@media (max-width: 600px) {
  .bot-dashboard, .bot {
    overflow-x: hidden;
  }
}

/* ═══ 3. MAIN CONTENT AREA ══════════════════════════════════════ */
.main {
  /* Smooth scrolling everywhere */
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
}
@media (max-width: 600px) {
  .main {
    height: calc(100dvh - 5.6rem); /* dvh accounts for mobile browser chrome */
    overflow-x: hidden;
  }
}
@media (min-width: 1920px) {
  .main {
    max-width: 2560px;
    margin: 0 auto;
  }
}

/* ═══ 4. HEADER ═════════════════════════════════════════════════ */
@media (max-width: 600px) {
  .deriv-header,
  .deriv-header > *,
  [class*=deriv-header] {
    /* Tighten header for mobile */
    padding-inline: 8px !important;
    gap: 6px !important;
  }
}

/* App logo — shrink on mobile */
@media (max-width: 480px) {
  .app-logo img, .app-logo svg {
    height: 28px !important;
    width: auto !important;
  }
}

/* Header auth actions — tighter spacing */
@media (max-width: 600px) {
  .auth-actions {
    gap: 4px !important;
    padding-block: 4px !important;
  }
  .auth-actions button {
    padding: 5px 10px !important;
    font-size: 1.15rem !important;
    border-radius: 12px !important;
    margin-inline-end: 4px !important;
    min-height: 36px;
  }
}

/* Demo reset button — hide label on very small screens, show icon only */
@media (max-width: 380px) {
  .header__demo-reset-btn {
    padding: 5px 8px !important;
    font-size: 0 !important; /* hide text */
  }
  .header__demo-reset-btn::before {
    content: "↺";
    font-size: 1.4rem;
  }
}

/* ═══ 5. TAB BAR ════════════════════════════════════════════════ */
.dc-tabs__list {
  /* Always scrollable horizontally */
  display: flex !important;
  flex-wrap: nowrap !important;
  overflow-x: auto !important;
  overflow-y: hidden !important;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.dc-tabs__list::-webkit-scrollbar {
  display: none;
}
.dc-tabs__list {
  scroll-snap-type: x proximity;
}
@media (max-width: 600px) {
  .dc-tabs__list {
    gap: 0 !important;
    padding: 0 !important;
  }
}

.dc-tabs__item {
  flex-shrink: 0;
  scroll-snap-align: start;
  white-space: nowrap;
}
@media (max-width: 900px) {
  .dc-tabs__item {
    height: 4.2rem !important;
    padding: 0 1rem !important;
    font-size: 1.1rem !important;
  }
  .dc-tabs__item svg {
    width: 14px !important;
    height: 14px !important;
    margin-inline-end: 3px !important;
  }
}
@media (max-width: 600px) {
  .dc-tabs__item {
    height: 3.8rem !important;
    padding: 0 0.8rem !important;
    font-size: 1rem !important;
    /* Hide icon on very small mobile to fit more tabs */
  }
  .dc-tabs__item svg {
    display: none !important;
  }
}
@media (max-width: 380px) {
  .dc-tabs__item {
    padding: 0 0.6rem !important;
    font-size: 0.95rem !important;
  }
}

/* Tab shadows (left/right scroll indicators) */
@media (max-width: 600px) {
  .tabs-shadow {
    width: 32px;
    height: 32px;
  }
}

/* ═══ 6. DASHBOARD PAGE ═════════════════════════════════════════ */
@media (max-width: 600px) {
  .dashboard__chart-wrapper {
    height: calc(100dvh - 9.8rem) !important;
  }
}

/* ═══ 7. CHART PAGE (75/25 grid) ════════════════════════════════ */
/* On mobile the trading panel goes below the chart */
@media (max-width: 900px) {
  .chart-wrapper-grid,
  [style*="gridTemplateColumns: 75% 25%"],
  [style*="grid-template-columns: 75% 25%"] {
    display: flex !important;
    flex-direction: column !important;
    overflow-y: auto !important;
  }
}

/* ChartTradePanel — full width on mobile */
@media (max-width: 900px) {
  .ctp {
    height: auto !important;
    min-height: 520px;
    border-left: none !important;
    border-top: 1px solid #e8e8e8;
  }
}
@media (max-width: 600px) {
  .ctp__digits {
    gap: 3px;
  }
}
@media (max-width: 600px) {
