    font-size: 16px;
  }
}
@media (max-width: 600px) {
  .ctp__circles {
    gap: 2px;
  }
}
@media (max-width: 600px) {
  .ctp__circle {
    width: 24px;
    height: 24px;
    font-size: 10px;
  }
}

/* ═══ 8. MANUAL TRADER ══════════════════════════════════════════ */
@media (max-width: 900px) {
  .manual-trader,
  .mt-page {
    flex-direction: column !important;
  }
}
@media (max-width: 600px) {
  .manual-trader,
  .mt-page {
    padding: 0.8rem !important;
  }
}

/* Manual trader panel */
@media (max-width: 900px) {
  .mtp-panel,
  [class*=mtp-] {
    width: 100% !important;
    max-width: 100% !important;
  }
