  .pro-hedge__leg-card {
    width: 100% !important;
  }
}
@media (max-width: 600px) {
  .pro-hedge__execute-btn, .pro-hedge__auto-btn {
    padding: 0.5rem 1rem !important;
    font-size: 1.1rem !important;
  }
