  .copy-trading__engines {
    flex-direction: column !important;
    gap: 1.2rem !important;
  }
}

/* ═══ 12. SCALPER BOTS ══════════════════════════════════════════ */
@media (max-width: 900px) {
  .scalper-bots,
  [class*=scalper] {
    flex-direction: column !important;
    padding: 1rem !important;
  }
}

/* ═══ 13. SPEED LAB ═════════════════════════════════════════════ */
@media (max-width: 900px) {
  [class*=speed-lab],
  [class*=speedlab] {
    flex-direction: column !important;
    padding: 1rem !important;
  }
}

/* ═══ 14. ANALYSIS PAGE ═════════════════════════════════════════ */
@media (max-width: 900px) {
  .analysis {
    padding: 1rem !important;
    flex-direction: column !important;
  }
}

/* ═══ 15. REPORTS ═══════════════════════════════════════════════ */
@media (max-width: 600px) {
  [class*=reports],
  [class*=report-] {
    padding: 1rem !important;
    font-size: 1.15rem !important;
  }
}

/* ═══ 16. MODALS ════════════════════════════════════════════════ */
@media (max-width: 600px) {
  .dc-dialog,
  [class*=deriv-modal],
  [class*=dc-modal] {
    width: calc(100vw - 2rem) !important;
    max-width: 100% !important;
    border-radius: 1.2rem !important;
    left: 1rem !important;
    right: 1rem !important;
    transform: none !important;
    margin: 0 !important;
  }
}

/* ═══ 17. NAV DRAWER ════════════════════════════════════════════ */
@media (max-width: 480px) {
  .nav-drawer__panel {
    width: 88vw !important;
  }
}
@media (max-width: 480px) {
  .nav-drawer__item {
    padding: 1rem 1.4rem !important;
    font-size: 1.3rem !important;
    min-height: 48px !important;
  }
}

/* ═══ 18. RUN PANEL / FLOATING BUTTONS ═════════════════════════ */
@media (max-width: 600px) {
  .main__run-strategy-wrapper {
    inset-inline-end: 0.8rem !important;
    top: 5rem !important;
  }
}

/* ═══ 19. SCROLLBAR POLISH ══════════════════════════════════════ */
* {
  scrollbar-width: thin;
  scrollbar-color: rgba(0, 200, 83, 0.3) transparent;
}
*::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}
*::-webkit-scrollbar-track {
  background: transparent;
}
*::-webkit-scrollbar-thumb {
  background: rgba(0, 200, 83, 0.25);
  border-radius: 10px;
}
@media (max-width: 600px) {
  * {
    /* Hide scrollbars on mobile — rely on native momentum scrolling */
    scrollbar-width: none;
  }
  *::-webkit-scrollbar {
    display: none;
  }
}

/* ═══ 20. TOASTS ════════════════════════════════════════════════ */
@media (max-width: 600px) {
  .Toastify__toast-container {
    width: calc(100vw - 2rem) !important;
    left: 1rem !important;
    right: 1rem !important;
    bottom: 1rem !important;
    transform: none !important;
  }
}

/* ═══ 21. FLOATERS (WhatsApp, Risk, AI) ════════════════════════ */
@media (max-width: 600px) {
  [class*=floating],
  [class*=float-btn],
  [class*=whatsapp] {
    /* Ensure floaters don't overlap the tab bar */
    bottom: 6rem !important;
  }
}

/* ═══ 22. GRID UTILITY: 2-col → 1-col on mobile ════════════════ */
@media (max-width: 600px) {
  [class*=__droprow],
  [class*=__row3],
  [class*=grid-2],
  [class*=two-col] {
    display: flex !important;
    flex-direction: column !important;
    gap: 8px !important;
  }
}
/* ═══ 23. LARGE SCREEN OPTIMIZATIONS ═══════════════════════════ */
@media (min-width: 1920px) {
  /* Give more breathing room on 24" monitors */
  .main__container {
    padding-inline: 2.4rem;
  }
  .dc-tabs__item {
    height: 5.2rem;
    padding: 0 2rem;
    font-size: 1.4rem;
  }
  /* Bigger touch targets on large screens too */
  button {
    min-height: 38px;
  }
}
/* ═══ 24. PORTRAIT → LANDSCAPE TRANSITION ON MOBILE ═══════════ */
@media (max-width: 900px) and (orientation: landscape) {
  .main {
    height: calc(100dvh - 5.2rem);
  }
  .dc-tabs__list {
    height: 3.8rem;
  }
}
/* ═══ 25. SAFE AREA (notch / home bar on iPhone / Android) ══════ */
@supports (padding: env(safe-area-inset-bottom)) {
  .main {
    padding-bottom: env(safe-area-inset-bottom);
  }
  .install-popup {
    bottom: calc(1.6rem + env(safe-area-inset-bottom));
  }
}
